import * as d3 from 'd3';
import {
  Sel, drawLabel, drawArrow, drawStepBox,
  drawTensor, drawMatrixBlock, fmtNum,
} from '../primitives';
import { ComputationGraph } from '../../graph/types';
import { ComponentDef } from '../../components/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

interface AttnStep {
  id: number;
  label: string;
  shortLabel: string;
  formula: string;
  explanation: string;
  code: { title: string; lines: string[] };
  svgGroup: string;
  color: string;
  fill: string;
}

function lbl(g: Sel, x: number, y: number, text: string, opts: { size?: number; weight?: string; color?: string; font?: string; anchor?: 'start' | 'middle' | 'end' } = {}): void {
  drawLabel(g, x, y, text, opts);
}

function arrowDown(g: Sel, x: number, y1: number, y2: number, color = '#78909c'): void {
  drawArrow(g, x, y1, x, y2, { color });
}

function arrowH(g: Sel, x1: number, x2: number, y: number, color = '#78909c'): void {
  drawArrow(g, x1, y, x2, y, { color });
}

function drawHeader(g: Sel, cx: number, y: number, title: string, subtitle: string): number {
  lbl(g, cx, y, title, { size: 16, weight: '700' });
  y += 22;
  lbl(g, cx, y, subtitle, { size: 10, color: '#888' });
  return y + 40;
}

function matrixBBox(x: number, y: number, rows: number, cols: number, cellSize: number) {
  return {
    x, y, width: cols * cellSize, height: rows * cellSize,
    cx: x + (cols * cellSize) / 2, cy: y + (rows * cellSize) / 2,
    right: x + cols * cellSize, bottom: y + rows * cellSize,
  };
}

function drawSmallMatrix(g: Gsel, x: number, y: number, rows: number, cols: number, cellSize: number, label: string, color: string, dimLabel?: string): void {
  const group = g.append('g');
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      group.append('rect')
        .attr('x', x + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', d3.interpolate(color, '#ffffff')(0.15 + Math.random() * 0.25))
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }
  lbl(group as Sel, x + (cols * cellSize) / 2, y + rows * cellSize + 12, label, { size: 8, color: '#666' });
  if (dimLabel) {
    lbl(group as Sel, x + (cols * cellSize) / 2, y + rows * cellSize + 24, dimLabel, { size: 7, color: '#888', font: 'monospace' });
  }
}

function drawAttentionHeatmap(
  g: Gsel, x: number, y: number, seqLen: number,
  maskType: 'causal' | 'none' | 'sliding' | 'sparse',
  windowSize?: number,
): number {
  const displaySize = Math.min(seqLen, 12);
  const cellSize = Math.min(14, 160 / displaySize);
  const gridW = displaySize * cellSize;
  const group = g.append('g');

  for (let r = 0; r < displaySize; r++) {
    for (let c = 0; c < displaySize; c++) {
      let isMasked = false;
      if (maskType === 'causal') isMasked = c > r;
      else if (maskType === 'sliding' && windowSize) isMasked = Math.abs(c - r) > windowSize;
      else if (maskType === 'sparse') {
        const isLocal = Math.abs(c - r) <= 2;
        const isGlobal = c < 2 || r < 2;
        const isRandom = ((c * 7 + r * 13) % 5) === 0;
        isMasked = !(isLocal || isGlobal || isRandom);
      }
      const val = isMasked ? 0 : Math.random() * 0.6 + 0.1;
      group.append('rect')
        .attr('x', x + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', isMasked ? '#f5f5f5' : d3.interpolateOranges(val))
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }

  // Add labels around axes
  if (maskType === 'causal') {
    lbl(group as Sel, x - 10, y + gridW / 2, 'query i', { size: 8, color: '#666', anchor: 'end' });
    lbl(group as Sel, x + gridW / 2, y - 8, 'key j', { size: 8, color: '#666' });
    // diagonal line
    group.append('line')
      .attr('x1', x).attr('y1', y)
      .attr('x2', x + gridW).attr('y2', y + gridW)
      .attr('stroke', '#ef4444').attr('stroke-width', 1).attr('stroke-dasharray', '3,3');
    lbl(group as Sel, x + gridW + 8, y + gridW / 2 - 10, 'future', { size: 7, color: '#ef4444' });
    lbl(group as Sel, x + gridW / 2 - 15, y + gridW + 22, 'causal mask', { size: 8, color: '#ef4444' });
  } else {
    lbl(group as Sel, x + gridW / 2, y + gridW + 14, `Attention scores (${maskType})`, { size: 9, color: '#666' });
  }

  return gridW + 40;
}

function drawMaskPattern(
  g: Gsel, x: number, y: number, seqLen: number,
  pattern: 'causal' | 'sliding' | 'sparse' | 'none',
  windowSize?: number,
): number {
  const displaySize = Math.min(seqLen, 14);
  const cellSize = Math.min(10, 140 / displaySize);
  const gridW = displaySize * cellSize;
  const group = g.append('g');

  for (let r = 0; r < displaySize; r++) {
    for (let c = 0; c < displaySize; c++) {
      let allowed = true;
      if (pattern === 'causal') allowed = c <= r;
      else if (pattern === 'sliding' && windowSize) allowed = Math.abs(c - r) <= windowSize;
      else if (pattern === 'sparse') {
        const isLocal = Math.abs(c - r) <= 2;
        const isGlobal = c < 2 || r < 2;
        const isRandom = ((c * 7 + r * 13) % 5) === 0;
        allowed = isLocal || isGlobal || isRandom;
      }
      group.append('rect')
        .attr('x', x + c * cellSize)
        .attr('y', y + r * cellSize)
        .attr('width', cellSize)
        .attr('height', cellSize)
        .attr('fill', allowed ? '#22c55e' : '#fee2e2')
        .attr('stroke', '#e0e0e0')
        .attr('stroke-width', 0.3);
    }
  }

  const labelMap: Record<string, string> = {
    causal: 'Causal mask: white = blocked',
    sliding: `Sliding window: w=${windowSize}`,
    sparse: 'Sparse: local + global + random',
    none: 'No mask: all allowed',
  };
  lbl(group as Sel, x + gridW / 2, y + gridW + 14, labelMap[pattern], { size: 8, color: '#666' });
  return gridW + 30;
}

function drawHeadSplit(g: Gsel, cx: number, y: number, nHeads: number, dHead: number, seqLen: number): number {
  const displayHeads = Math.min(nHeads, 6);
  const cellSize = 8;
  const cols = 3;
  const rows = 5;
  const headW = cols * cellSize;
  const headH = rows * cellSize;
  const gap = 12;
  const totalW = displayHeads * headW + (displayHeads - 1) * gap;
  const startX = cx - totalW / 2;

  for (let h = 0; h < displayHeads; h++) {
    const hx = startX + h * (headW + gap);
    const headGroup = g.append('g');
    drawSmallMatrix(headGroup, hx, y, rows, cols, cellSize, `h${h}`, '#dbeafe', `[${seqLen}, ${dHead}]`);
  }

  if (nHeads > displayHeads) {
    lbl(g as Sel, cx + totalW / 2 + 16, y + headH / 2, `...${nHeads - displayHeads} more`, { size: 8, color: '#888', anchor: 'start' });
  }

  lbl(g as Sel, cx, y + headH + 28, `Reshape: [batch, seq=${seqLen}, d_model] → [batch, ${nHeads}, seq=${seqLen}, d_head=${dHead}]`, { size: 9, color: '#666' });
  return headH + 48;
}

// ── Standard MHA ──────────────────────────────────────────────────────────────

function renderStandard(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'Multi-Head Attention (Standard)', `d_model=${dModel}  n_heads=${nHeads}  seq_len=${seqLen}  d_head=${dHead}`);

  // Input
  const sIn = g.append('g').attr('class', 'step-node');
  drawTensor(sIn as Sel, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  // Three projection matrices side by side
  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  // Arrows from input to matrices
  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  // Output tensors
  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  // Arrows from matrices to outputs
  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: Split heads
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 150, y, 300, 42, 'Step 2 — Split into Heads', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `[batch, n_heads, seq, d_head]` });
  y += 58;

  y += drawHeadSplit(s2, cx, y, nHeads, dHead, seqLen);

  // Step 3: Compute attention scores
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Scaled Dot-Product Scores', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'scores = Q @ K^T / √d_head' });
  y += 58;

  // QK^T matrix multiplication illustration
  const q3 = matrixBBox(cx - 130, y, 5, 5, 12);
  const kt3 = matrixBBox(cx - 30, y, 5, 5, 12);
  const s3out = matrixBBox(cx + 80, y, 5, 5, 12);
  drawSmallMatrix(s3, q3.x, q3.y, 5, 5, 12, 'Q', '#dbeafe', `[${seqLen}, ${dHead}]`);
  lbl(s3 as Sel, cx - 55, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, kt3.x, kt3.y, 5, 5, 12, 'K^T', '#dbeafe', `[${dHead}, ${seqLen}]`);
  arrowH(s3 as Sel, kt3.right + 4, s3out.x - 4, y + 30, '#9333ea');
  drawSmallMatrix(s3, s3out.x, s3out.y, 5, 5, 12, 'scores', '#f3e8ff', `[${seqLen}, ${seqLen}]`);
  lbl(s3 as Sel, cx + 80, y + 102, `÷ √${dHead}`, { size: 9, color: '#9333ea' });
  y += 120;

  // Step 4: Apply mask + softmax
  const s4 = g.append('g').attr('class', 'step-node step-attn-mask').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 150, y, 300, 42, 'Step 4 — Causal Mask + Softmax', { step: 4, fill: '#fef3c7', stroke: '#d97706', formula: 'A = softmax(mask(scores))' });
  y += 58;

  const heatH = drawAttentionHeatmap(s4, cx - 80, y, seqLen, 'causal');
  y += heatH + 10;

  // Step 5: Weighted sum with V
  const s5 = g.append('g').attr('class', 'step-node step-attn-weighted').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 160, y, 320, 42, 'Step 5 — Weighted Sum A · V', { step: 5, fill: '#f3e8ff', stroke: '#9333ea', formula: 'head_out = A @ V' });
  y += 58;

  const a5 = matrixBBox(cx - 130, y, 5, 5, 12);
  const v5 = matrixBBox(cx - 30, y, 5, 4, 12);
  const o5 = matrixBBox(cx + 80, y, 5, 4, 12);
  drawSmallMatrix(s5, a5.x, a5.y, 5, 5, 12, 'A', '#fef3c7', `[${seqLen}, ${seqLen}]`);
  lbl(s5 as Sel, cx - 55, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s5, v5.x, v5.y, 5, 4, 12, 'V', '#dbeafe', `[${seqLen}, ${dHead}]`);
  arrowH(s5 as Sel, v5.right + 4, o5.x - 4, y + 24, '#9333ea');
  drawSmallMatrix(s5, o5.x, o5.y, 5, 4, 12, 'head_out', '#f3e8ff', `[${seqLen}, ${dHead}]`);
  y += 100;

  // Step 6: Concatenate and project
  const s6 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '6');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s6 as Sel, cx - 150, y, 300, 42, 'Step 6 — Concat Heads + Output Projection', { step: 6, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;

  // concat representation
  const headGap = 6;
  const headW = 20; // 5 rows x 2 cols x 10 cell
  const headsShown = Math.min(nHeads, 4);
  let lastHeadRight = cx - 100;
  for (let h = 0; h < headsShown; h++) {
    const hx = cx - 100 + h * (headW + headGap);
    drawSmallMatrix(s6, hx, y, 5, 2, 10, `h${h}`, '#f3e8ff', `[${seqLen}, ${dHead}]`);
    lastHeadRight = hx + headW;
  }
  if (nHeads > 4) lbl(s6 as Sel, lastHeadRight + 14, y + 25, `...${nHeads - 4}`, { size: 8, color: '#888', anchor: 'start' });

  const woX = cx + 110;
  arrowH(s6 as Sel, lastHeadRight + 6, woX - 2, y + 25, '#ea580c');
  drawMatrixBlock(s6 as Sel, woX, y, { width: 70, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  arrowH(s6 as Sel, woX + 72, woX + 92, y + 25, '#ea580c');
  drawTensor(s6 as Sel, woX + 94, y + 10, 100, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 90;

  // Params and FLOPs
  const totalParams = dModel * dModel * 4;
  lbl(g, cx, y, `Params: ${fmtNum(totalParams)}  (4 × ${fmtNum(dModel * dModel)})`, { size: 10, color: '#2563eb', weight: '600' });
  y += 18;
  lbl(g, cx, y, `FLOPs: O(n_heads · seq² · d_head) attention + O(seq · 4d²) projections`, { size: 10, color: 'var(--text-muted)' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Project to Q, K, V', shortLabel: 'Q/K/V Projection',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Three independent linear projections transform the input x into query, key, and value tensors. Each weight matrix is [${dModel}, ${dModel}], so this step contributes 3 × ${fmtNum(dModel * dModel)} = ${fmtNum(dModel * dModel * 3)} parameters. Q and K are used to compute compatibility scores; V carries the information to be aggregated.`,
      code: { title: 'Q/K/V Projection', lines: [`self.Wq = nn.Linear(${dModel}, ${dModel}, bias=False)`, `self.Wk = nn.Linear(${dModel}, ${dModel}, bias=False)`, `self.Wv = nn.Linear(${dModel}, ${dModel}, bias=False)`, '', `q = x @ Wq  # [b, ${seqLen}, ${dModel}]`, `k = x @ Wk  # [b, ${seqLen}, ${dModel}]`, `v = x @ Wv  # [b, ${seqLen}, ${dModel}]`] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: `[b, ${seqLen}, ${dModel}] → [b, ${nHeads}, ${seqLen}, ${dHead}]`,
      explanation: `Each of Q/K/V is reshaped: the d_model dimension (${dModel}) is split into ${nHeads} independent heads of dimension ${dHead} = ${dModel}/${nHeads}. The transpose puts the head dimension before the sequence dimension so every head attends over the full sequence in parallel.`,
      code: { title: 'Head Split', lines: [`q = q.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `k = k.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `v = v.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Compute Attention Scores', shortLabel: 'QK^T',
      formula: `scores = Q @ K^T / √${dHead}`,
      explanation: `For every head, multiply Q [${seqLen}, ${dHead}] by K^T [${dHead}, ${seqLen}] to obtain an [${seqLen}, ${seqLen}] compatibility matrix. The scale factor 1/√${dHead} keeps dot-product magnitudes stable as d_head grows, preventing softmax from saturating.`,
      code: { title: 'Scores', lines: [`scores = (q @ k.transpose(-2, -1)) / math.sqrt(${dHead})  # [b, ${nHeads}, ${seqLen}, ${seqLen}]`] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Causal Mask + Softmax', shortLabel: 'Mask',
      formula: 'A = softmax(mask(scores))',
      explanation: `A causal mask zeros out positions j > i (future tokens), which is equivalent to setting those scores to -∞ before softmax. The result is an [${seqLen}, ${seqLen}] attention probability matrix A where each row sums to 1 and only current/past positions have nonzero weight.`,
      code: { title: 'Mask + Softmax', lines: [`mask = torch.tril(torch.ones(${seqLen}, ${seqLen}))`, `scores = scores.masked_fill(mask == 0, float('-inf'))`, `attn = F.softmax(scores, dim=-1)`] },
      svgGroup: 'step-attn-mask', color: '#d97706', fill: '#fef3c7' },
    { id: 5, label: 'Weighted Sum with V', shortLabel: 'A @ V',
      formula: 'head_out = A @ V',
      explanation: `Each position i computes a weighted average of value vectors V using its attention distribution A[i, :]. With A [${seqLen}, ${seqLen}] and V [${seqLen}, ${dHead}], each head output is [${seqLen}, ${dHead}].`,
      code: { title: 'Weighted Sum', lines: [`out = attn @ v  # [b, ${nHeads}, ${seqLen}, ${dHead}]`] },
      svgGroup: 'step-attn-weighted', color: '#9333ea', fill: '#f3e8ff' },
    { id: 6, label: 'Concatenate and Project', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `The ${nHeads} head outputs are transposed back and reshaped to [b, ${seqLen}, ${dModel}], then projected through W_o [${dModel}, ${dModel}]. This final linear layer mixes information across heads and restores the original model dimension.`,
      code: { title: 'Output Projection', lines: [`self.Wo = nn.Linear(${dModel}, ${dModel}, bias=False)`, `out = out.transpose(1, 2).reshape(b, ${seqLen}, ${dModel})`, `return self.Wo(out)  # [b, ${seqLen}, ${dModel}]`] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── GQA / MQA ─────────────────────────────────────────────────────────────────

function renderGQAMQA(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number, isMQA: boolean)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const nKVHeads = isMQA ? 1 : Math.max(1, Math.floor(nHeads / 4));
  const qPerKV = Math.floor(nHeads / nKVHeads);
  const variant = isMQA ? 'Multi-Query' : 'Grouped-Query';
  let y = 28;

  y = drawHeader(g, cx, y, `Attention — ${variant}`, `d_model=${dModel}  n_heads=${nHeads}  n_kv_heads=${nKVHeads}  d_head=${dHead}`);

  // Input
  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: Asymmetric QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Asymmetric Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: `Q: [d, d], K/V: [d, ${dHead}×${nKVHeads}]` });
  y += 58;

  // Wq full
  drawMatrixBlock(s1 as Sel, cx - 160, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  // Wk/Wv smaller
  drawMatrixBlock(s1 as Sel, cx - 30, y, { width: 55, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dHead * nKVHeads}]`, fill: '#dcfce7', stroke: '#16a34a' });
  drawMatrixBlock(s1 as Sel, cx + 45, y, { width: 55, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dHead * nKVHeads}]`, fill: '#dcfce7', stroke: '#16a34a' });

  arrowDown(s1 as Sel, cx - 120, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx - 2, y - 22, y - 2, '#16a34a');
  arrowDown(s1 as Sel, cx + 72, y - 22, y - 2, '#16a34a');

  drawTensor(s1 as Sel, cx - 160, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 30, y + 70, 68, 24, `K [b, ${seqLen}, ${dHead * nKVHeads}]`, '#dcfce7', '#16a34a');
  drawTensor(s1 as Sel, cx + 45, y + 70, 68, 24, `V [b, ${seqLen}, ${dHead * nKVHeads}]`, '#dcfce7', '#16a34a');

  arrowDown(s1 as Sel, cx - 120, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx - 2, y + 55, y + 70, '#16a34a');
  arrowDown(s1 as Sel, cx + 72, y + 55, y + 70, '#16a34a');
  y += 118;

  // Step 2: Head split (Q many heads, KV few heads)
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Split Heads: Q dense, KV shared', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `Q: [${nHeads} heads], K/V: [${nKVHeads} heads]` });
  y += 58;

  // Q heads
  const qHeadsShown = Math.min(nHeads, 6);
  const qCell = 8, qCols = 3, qRows = 5;
  const qHeadW = qCols * qCell;
  const qGap = 6;
  const qTotalW = qHeadsShown * qHeadW + (qHeadsShown - 1) * qGap;
  const qStartX = cx - 180 - qTotalW / 2 + qHeadW / 2;
  lbl(s2 as Sel, cx - 180, y - 6, `Q heads (${nHeads})`, { size: 9, weight: '600', color: '#2563eb' });
  for (let h = 0; h < qHeadsShown; h++) {
    drawSmallMatrix(s2, qStartX + h * (qHeadW + qGap), y, qRows, qCols, qCell, `h${h}`, '#dbeafe', `[${seqLen}, ${dHead}]`);
  }
  if (nHeads > qHeadsShown) {
    lbl(s2 as Sel, qStartX + qHeadsShown * (qHeadW + qGap) - qGap / 2, y + qRows * qCell / 2, `...${nHeads - qHeadsShown}`, { size: 8, color: '#888', anchor: 'start' });
  }

  // KV heads
  const kvHeadsShown = Math.min(nKVHeads, 4);
  const kvCell = 8, kvCols = 3, kvRows = 5;
  const kvHeadW = kvCols * kvCell;
  const kvGap = 6;
  const kvTotalW = kvHeadsShown * kvHeadW + (kvHeadsShown - 1) * kvGap;
  const kvStartX = cx + 80 - kvTotalW / 2 + kvHeadW / 2;
  lbl(s2 as Sel, cx + 80, y - 6, `K/V heads (${nKVHeads})`, { size: 9, weight: '600', color: '#16a34a' });
  for (let h = 0; h < kvHeadsShown; h++) {
    drawSmallMatrix(s2, kvStartX + h * (kvHeadW + kvGap), y, kvRows, kvCols, kvCell, `h${h}`, '#dcfce7', `[${seqLen}, ${dHead}]`);
  }
  if (nKVHeads > kvHeadsShown) {
    lbl(s2 as Sel, kvStartX + kvHeadsShown * (kvHeadW + kvGap) - kvGap / 2, y + kvRows * kvCell / 2, `...${nKVHeads - kvHeadsShown}`, { size: 8, color: '#888', anchor: 'start' });
  }
  y += Math.max(qRows, kvRows) * kvCell + 32;

  // Step 3: Broadcast KV to Q
  const s3 = g.append('g').attr('class', 'step-node step-attn-broadcast').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Broadcast K/V to Q Heads', { step: 3, fill: '#ffedd5', stroke: '#ea580c', formula: `Each KV head → ${qPerKV} Q heads` });
  y += 58;

  // Broadcast arrows: KV heads drawn above, Q heads drawn below, lines go top→bottom
  const qShown3 = Math.min(nHeads, 6);
  const kvShown3 = Math.min(nKVHeads, 4);
  const cell3 = 7, cols3 = 3, rows3 = 4;
  const headW3 = cols3 * cell3;
  const gap3 = 6;
  const qTotalW3 = qShown3 * headW3 + (qShown3 - 1) * gap3;
  const kvTotalW3 = kvShown3 * headW3 + (kvShown3 - 1) * gap3;
  const qStart3 = cx - qTotalW3 / 2;
  const kvStart3 = cx - kvTotalW3 / 2;
  const rowYKV = y + 10;
  const rowYQ = rowYKV + rows3 * cell3 + 28;

  // KV row (top)
  lbl(s3 as Sel, cx, rowYKV - 10, `K/V heads (${nKVHeads})`, { size: 8, weight: '600', color: '#16a34a' });
  for (let h = 0; h < kvShown3; h++) {
    drawSmallMatrix(s3, kvStart3 + h * (headW3 + gap3), rowYKV, rows3, cols3, cell3, `kv${h}`, '#dcfce7', `[${seqLen}, ${dHead}]`);
  }
  // Q row (bottom)
  lbl(s3 as Sel, cx, rowYQ - 10, `Q heads (${nHeads})`, { size: 8, weight: '600', color: '#2563eb' });
  for (let h = 0; h < qShown3; h++) {
    drawSmallMatrix(s3, qStart3 + h * (headW3 + gap3), rowYQ, rows3, cols3, cell3, `q${h}`, '#dbeafe', `[${seqLen}, ${dHead}]`);
  }

  // Lines from bottom of each KV head to top of the Q heads it feeds (downward)
  for (let q = 0; q < qShown3; q++) {
    const kvIdx = Math.floor(q / qPerKV);
    if (kvIdx >= kvShown3) continue;
    const kx = kvStart3 + kvIdx * (headW3 + gap3) + headW3 / 2;
    const qx = qStart3 + q * (headW3 + gap3) + headW3 / 2;
    g.append('line')
      .attr('x1', kx).attr('y1', rowYKV + rows3 * cell3)
      .attr('x2', qx).attr('y2', rowYQ)
      .attr('stroke', '#ea580c').attr('stroke-width', 1).attr('opacity', 0.6);
  }
  lbl(s3 as Sel, cx, rowYQ + rows3 * cell3 + 22, `${nKVHeads} KV heads → ${nHeads} Q heads (1 KV shared by ${qPerKV} Q)`, { size: 9, color: '#666' });
  y += 88;

  // Step 4: Attention
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 42, 'Step 4 — Attention (Shared K/V)', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'softmax(QK^T / √d) · V' });
  y += 58;

  drawAttentionHeatmap(s4, cx - 80, y, seqLen, 'causal');
  y += 190;

  // Step 5: Output projection
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 100, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  // Params
  const qParams = dModel * dModel;
  const kvParams = dModel * dHead * nKVHeads;
  const outParams = dModel * dModel;
  const totalParams = qParams + kvParams * 2 + outParams;
  lbl(g, cx, y, `Params: ${fmtNum(totalParams)}  (Q ${fmtNum(qParams)} + K/V ${fmtNum(kvParams * 2)} + Out ${fmtNum(outParams)})`, { size: 10, color: '#2563eb', weight: '600' });
  y += 18;
  lbl(g, cx, y, `KV cache reduction: ${nKVHeads}/${nHeads} of standard`, { size: 10, color: '#ea580c' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Asymmetric Q/K/V Projection', shortLabel: 'Asymmetric QKV',
      formula: `W_q: [${dModel}, ${dModel}], W_k/v: [${dModel}, ${dHead * nKVHeads}]`,
      explanation: `Q is projected to full d_model (${dModel}) so every query head has unique parameters. K/V are projected to only ${dHead * nKVHeads} dimensions (${nKVHeads} heads × d_head ${dHead}), cutting KV cache memory to ${nKVHeads}/${nHeads} of standard MHA.`,
      code: { title: 'Asymmetric Projection', lines: [`self.Wq = nn.Linear(${dModel}, ${dModel}, bias=False)`, `self.Wk = nn.Linear(${dModel}, ${dHead * nKVHeads}, bias=False)`, `self.Wv = nn.Linear(${dModel}, ${dHead * nKVHeads}, bias=False)`, '', `q = x @ Wq  # [b, ${seqLen}, ${dModel}]`, `k = x @ Wk  # [b, ${seqLen}, ${dHead * nKVHeads}]`, `v = x @ Wv  # [b, ${seqLen}, ${dHead * nKVHeads}]`] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Split Heads (Q dense, KV shared)', shortLabel: 'Head Split',
      formula: `Q: [b, ${nHeads}, ${seqLen}, ${dHead}]  K/V: [b, ${nKVHeads}, ${seqLen}, ${dHead}]`,
      explanation: `Q is reshaped into ${nHeads} heads of dimension ${dHead}. K/V are reshaped into only ${nKVHeads} heads; each KV head covers the same sequence length ${seqLen} but with a narrower representation.`,
      code: { title: 'Split', lines: [`q = q.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `k = k.view(b, ${seqLen}, ${nKVHeads}, ${dHead}).transpose(1, 2)`, `v = v.view(b, ${seqLen}, ${nKVHeads}, ${dHead}).transpose(1, 2)`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Broadcast K/V to Q Heads', shortLabel: 'KV Broadcast',
      formula: `K/V: [${nKVHeads}] → [${nHeads}] (1 KV per ${qPerKV} Q)`,
      explanation: `Each KV head is reused (broadcast) for ${qPerKV} query heads. The attention scores still compute QK^T per query head, but K/V are shared, so memory bandwidth and cache size drop proportionally.`,
      code: { title: 'Broadcast', lines: [`# Expand KV heads to match Q head count`, `k = k.repeat_interleave(${qPerKV}, dim=1)  # [b, ${nHeads}, seq, ${dHead}]`, `v = v.repeat_interleave(${qPerKV}, dim=1)  # [b, ${nHeads}, seq, ${dHead}]`] },
      svgGroup: 'step-attn-broadcast', color: '#ea580c', fill: '#ffedd5' },
    { id: 4, label: 'Attention', shortLabel: 'Attention',
      formula: 'softmax(QK^T / √d_head) · V',
      explanation: `After broadcast, every query head attends with its own Q but shares K/V. The attention matrix shape is [${seqLen}, ${seqLen}] per head, identical to MHA, but KV cache stores only ${nKVHeads} sets per layer.`,
      code: { title: 'Attention', lines: [`scores = (q @ k.transpose(-2, -1)) / math.sqrt(${dHead})`, `attn = F.softmax(scores.masked_fill(mask == 0, float('-inf')), dim=-1)`, `out = attn @ v  # [b, ${nHeads}, ${seqLen}, ${dHead}]`] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Head outputs are concatenated back to d_model (${dModel}) and projected through W_o. Despite fewer K/V parameters, the output dimension and expressiveness of the Q projection are preserved.`,
      code: { title: 'Output', lines: [`out = out.transpose(1, 2).reshape(b, ${seqLen}, ${dModel})`, `return self.Wo(out)  # [b, ${seqLen}, ${dModel}]`] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Cross-Attention ───────────────────────────────────────────────────────────

function renderCrossAttention(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const kvSeqLen = seqLen * 2;
  let y = 28;

  y = drawHeader(g, cx, y, 'Cross-Attention (Encoder→Decoder)', `d_model=${dModel}  n_heads=${nHeads}  q_seq=${seqLen}  kv_seq=${kvSeqLen}`);

  // Two inputs
  const sIn = g.append('g').attr('class', 'step-node');
  drawTensor(sIn as Sel, cx - 180, y, 140, 28, `decoder [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(sIn as Sel, cx + 40, y, 140, 28, `encoder [b, ${kvSeqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 50;

  // Step 1: Q from decoder, K/V from encoder
  const s1 = g.append('g').attr('class', 'step-node step-attn-cross').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 170, y, 340, 42, 'Step 1 — Q from Decoder, K/V from Encoder', { step: 1, fill: '#dbeafe', stroke: '#2563eb', formula: 'Q = dec·W_q, K/V = enc·W_k/v' });
  y += 58;

  // Decoder path
  drawMatrixBlock(s1 as Sel, cx - 160, y, { width: 70, height: 50, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s1 as Sel, cx - 160, y + 65, 70, 22, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  // Encoder path
  drawMatrixBlock(s1 as Sel, cx - 35, y, { width: 55, height: 50, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dcfce7', stroke: '#16a34a' });
  drawTensor(s1 as Sel, cx - 35, y + 65, 55, 22, `K [b, ${kvSeqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  drawMatrixBlock(s1 as Sel, cx + 35, y, { width: 55, height: 50, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dcfce7', stroke: '#16a34a' });
  drawTensor(s1 as Sel, cx + 35, y + 65, 55, 22, `V [b, ${kvSeqLen}, ${dModel}]`, '#dcfce7', '#16a34a');

  arrowDown(s1 as Sel, cx - 125, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx - 7, y - 22, y - 2, '#16a34a');
  arrowDown(s1 as Sel, cx + 62, y - 22, y - 2, '#16a34a');
  arrowDown(s1 as Sel, cx - 125, y + 50, y + 65, '#2563eb');
  arrowDown(s1 as Sel, cx - 7, y + 50, y + 65, '#16a34a');
  arrowDown(s1 as Sel, cx + 62, y + 50, y + 65, '#16a34a');
  y += 113;

  // Step 2: Split heads (Q from decoder, K/V from encoder)
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Split Heads (Q vs K/V lengths differ)', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `Q: [b, ${nHeads}, ${seqLen}, ${dHead}]  K/V: [b, ${nHeads}, ${kvSeqLen}, ${dHead}]` });
  y += 58;

  // Q heads
  const qHeadsShown = Math.min(nHeads, 4);
  const qCell = 8, qCols = 3, qRows = 5;
  const qHeadW = qCols * qCell;
  const qGap = 8;
  const qTotalW = qHeadsShown * qHeadW + (qHeadsShown - 1) * qGap;
  const qStartX = cx - 170;
  lbl(s2 as Sel, qStartX + qTotalW / 2, y - 6, `Q heads (seq=${seqLen})`, { size: 9, weight: '600', color: '#2563eb' });
  for (let h = 0; h < qHeadsShown; h++) {
    drawSmallMatrix(s2, qStartX + h * (qHeadW + qGap), y, qRows, qCols, qCell, `h${h}`, '#dbeafe', `[${seqLen}, ${dHead}]`);
  }

  // K/V heads
  const kvHeadsShown = Math.min(nHeads, 4);
  const kvCols = 3, kvRows = 6; // taller to show longer kv seq
  const kvCell = 8;
  const kvHeadW = kvCols * kvCell;
  const kvGap = 8;
  const kvTotalW = kvHeadsShown * kvHeadW + (kvHeadsShown - 1) * kvGap;
  const kvStartX = cx + 30;
  lbl(s2 as Sel, kvStartX + kvTotalW / 2, y - 6, `K/V heads (seq=${kvSeqLen})`, { size: 9, weight: '600', color: '#16a34a' });
  for (let h = 0; h < kvHeadsShown; h++) {
    drawSmallMatrix(s2, kvStartX + h * (kvHeadW + kvGap), y, kvRows, kvCols, kvCell, `h${h}`, '#dcfce7', `[${kvSeqLen}, ${dHead}]`);
  }
  y += Math.max(qRows, kvRows) * kvCell + 48;

  // Step 3: Full attention (no causal mask)
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Full Attention (No Causal Mask)', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(QK^T / √d) · V' });
  y += 58;

  drawAttentionHeatmap(s3, cx - 80, y, seqLen, 'none');
  y += 190;

  // Step 4: Output
  const s4 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 130, y, 260, 42, 'Step 4 — Output Projection', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s4 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s4 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const totalParams = dModel * dModel * 4;
  lbl(g, cx, y, `Params: ${fmtNum(totalParams)}`, { size: 10, color: '#2563eb', weight: '600' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q from Decoder, K/V from Encoder', shortLabel: 'Separate Sources',
      formula: 'Q = decoder · W_q, K/V = encoder · W_k/v',
      explanation: `Cross-attention uses queries from the decoder target sequence (length ${seqLen}) and keys/values from the encoder source sequence (length ${kvSeqLen}). This lets the decoder attend to the entire source while generating each target token.`,
      code: { title: 'Cross QKV', lines: [`q = decoder_hidden @ Wq   # [b, ${seqLen}, ${dModel}]`, `k = encoder_output @ Wk   # [b, ${kvSeqLen}, ${dModel}]`, `v = encoder_output @ Wv   # [b, ${kvSeqLen}, ${dModel}]`] },
      svgGroup: 'step-attn-cross', color: '#2563eb', fill: '#dbeafe' },
    { id: 2, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: `Q: [b, ${nHeads}, ${seqLen}, ${dHead}]  K/V: [b, ${nHeads}, ${kvSeqLen}, ${dHead}]`,
      explanation: `Q, K, V are split into ${nHeads} heads. Q keeps decoder length ${seqLen}; K/V keep encoder length ${kvSeqLen}, so attention scores become [${seqLen}, ${kvSeqLen}].`,
      code: { title: 'Split', lines: [`q = q.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `k = k.view(b, ${kvSeqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `v = v.view(b, ${kvSeqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Full Attention', shortLabel: 'Full Attention',
      formula: 'softmax(QK^T / √d_head) · V',
      explanation: `Each of the ${seqLen} decoder positions attends to all ${kvSeqLen} encoder positions. No causal mask is needed because the source sequence is complete.`,
      code: { title: 'Full Attention', lines: [`scores = (q @ k.transpose(-2, -1)) / sqrt(${dHead})  # [b, h, ${seqLen}, ${kvSeqLen}]`, 'attn = softmax(scores, dim=-1)  # no mask', 'out = attn @ v  # [b, h, q_len, d_head]'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate ${nHeads} head outputs back to d_model and project through W_o. Output length matches the query sequence (${seqLen}).`,
      code: { title: 'Output', lines: ['out = out.transpose(1, 2).reshape(b, q_len, d)', 'return self.Wo(out)  # [b, q_len, d_model]'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Bidirectional ─────────────────────────────────────────────────────────────

function renderBidirectional(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'Bidirectional Attention (BERT/Encoder)', `d_model=${dModel}  n_heads=${nHeads}  seq_len=${seqLen}  d_head=${dHead}`);

  // Input
  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: Split heads
  const s2 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 150, y, 300, 42, 'Step 2 — Split into Heads', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `[batch, n_heads, seq, d_head]` });
  y += 58;
  y += drawHeadSplit(s2, cx, y, nHeads, dHead, seqLen);

  // Step 3: Full attention matrix (no mask)
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Full Attention Matrix (No Mask)', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(QK^T / √d_head)' });
  y += 58;

  const q3 = matrixBBox(cx - 130, y, 5, 5, 12);
  const kt3 = matrixBBox(cx - 30, y, 5, 5, 12);
  const s3out = matrixBBox(cx + 80, y, 5, 5, 12);
  drawSmallMatrix(s3, q3.x, q3.y, 5, 5, 12, 'Q', '#dbeafe', `[${seqLen}, ${dHead}]`);
  lbl(s3 as Sel, cx - 55, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, kt3.x, kt3.y, 5, 5, 12, 'K^T', '#dbeafe', `[${dHead}, ${seqLen}]`);
  arrowH(s3 as Sel, kt3.right + 4, s3out.x - 4, y + 30, '#9333ea');
  drawSmallMatrix(s3, s3out.x, s3out.y, 5, 5, 12, 'scores', '#f3e8ff', `[${seqLen}, ${seqLen}]`);
  lbl(s3 as Sel, cx + 80, y + 102, `÷ √${dHead}`, { size: 9, color: '#9333ea' });
  y += 120;

  // Step 4: Softmax (no mask) + heatmap
  const s4 = g.append('g').attr('class', 'step-node step-attn-mask').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 150, y, 300, 42, 'Step 4 — Softmax over All Positions', { step: 4, fill: '#fef3c7', stroke: '#d97706', formula: 'A = softmax(scores)' });
  y += 58;

  drawAttentionHeatmap(s4, cx - 80, y, seqLen, 'none');
  y += 190;

  // Step 5: Weighted sum and output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 160, y, 320, 42, 'Step 5 — Weighted Sum + Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;

  const a5 = matrixBBox(cx - 130, y, 5, 5, 12);
  const v5 = matrixBBox(cx - 30, y, 5, 4, 12);
  const o5 = matrixBBox(cx + 80, y, 5, 4, 12);
  drawSmallMatrix(s5, a5.x, a5.y, 5, 5, 12, 'A', '#fef3c7', `[${seqLen}, ${seqLen}]`);
  lbl(s5 as Sel, cx - 55, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s5, v5.x, v5.y, 5, 4, 12, 'V', '#dbeafe', `[${seqLen}, ${dHead}]`);
  arrowH(s5 as Sel, v5.right + 4, o5.x - 4, y + 24, '#9333ea');
  drawSmallMatrix(s5, o5.x, o5.y, 5, 4, 12, 'head_out', '#f3e8ff', `[${seqLen}, ${dHead}]`);
  y += 80;
  const woX5 = cx - 40;
  drawMatrixBlock(s5 as Sel, woX5, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  arrowH(s5 as Sel, woX5 + 72, woX5 + 92, y + 25, '#ea580c');
  drawTensor(s5 as Sel, woX5 + 94, y + 10, 110, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Three linear projections produce Q, K, V from the same encoder input. Each weight matrix is [${dModel}, ${dModel}].`,
      code: { title: 'Projection', lines: [`self.Wq = nn.Linear(${dModel}, ${dModel}, bias=False)`, `self.Wk = nn.Linear(${dModel}, ${dModel}, bias=False)`, `self.Wv = nn.Linear(${dModel}, ${dModel}, bias=False)`, '', `q, k, v = x @ Wq, x @ Wk, x @ Wv  # [b, ${seqLen}, ${dModel}]`] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: `[b, ${seqLen}, ${dModel}] → [b, ${nHeads}, ${seqLen}, ${dHead}]`,
      explanation: `Q/K/V are reshaped into ${nHeads} heads of dimension ${dHead} = ${dModel}/${nHeads}.`,
      code: { title: 'Head Split', lines: [`q = q.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `k = k.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`, `v = v.view(b, ${seqLen}, ${nHeads}, ${dHead}).transpose(1, 2)`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Compute Attention Scores', shortLabel: 'QK^T',
      formula: `scores = Q @ K^T / √${dHead}`,
      explanation: `Per head: Q [${seqLen}, ${dHead}] @ K^T [${dHead}, ${seqLen}] → scores [${seqLen}, ${seqLen}]. All positions attend to all positions.`,
      code: { title: 'Scores', lines: [`scores = (q @ k.transpose(-2, -1)) / math.sqrt(${dHead})  # [b, ${nHeads}, ${seqLen}, ${seqLen}]`] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Softmax over All Positions', shortLabel: 'Softmax',
      formula: 'A = softmax(scores)',
      explanation: `Unlike causal attention, no positions are masked. Softmax is applied over the entire sequence, giving each token a context-aware representation using both left and right context.`,
      code: { title: 'Softmax', lines: [`attn = F.softmax(scores, dim=-1)  # [b, ${nHeads}, ${seqLen}, ${seqLen}]`] },
      svgGroup: 'step-attn-mask', color: '#d97706', fill: '#fef3c7' },
    { id: 5, label: 'Weighted Sum + Output', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `A [${seqLen}, ${seqLen}] @ V [${seqLen}, ${dHead}] produces head outputs of shape [${seqLen}, ${dHead}]. Heads are concatenated and projected back to d_model.`,
      code: { title: 'Output', lines: [`out = attn @ v  # [b, ${nHeads}, ${seqLen}, ${dHead}]`, `out = out.transpose(1, 2).reshape(b, ${seqLen}, ${dModel})`, `return self.Wo(out)  # [b, ${seqLen}, ${dModel}]`] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Sliding Window ────────────────────────────────────────────────────────────

function renderSlidingWindow(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const windowSize = Math.min(128, Math.floor(seqLen / 4));
  const displayWindow = Math.max(1, Math.floor(windowSize / (seqLen / 12)));
  let y = 28;

  y = drawHeader(g, cx, y, 'Sliding Window Attention (Mistral)', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  window_size=${windowSize}  seq_len=${seqLen}`);

  // Input
  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: Window mask
  const s2 = g.append('g').attr('class', 'step-node step-attn-window').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Sliding Window Mask', { step: 2, fill: '#fef3c7', stroke: '#d97706', formula: `attend to [i-${windowSize}, i]` });
  y += 58;

  drawMaskPattern(s2, cx - 70, y, seqLen, 'sliding', displayWindow);
  y += 170;

  // Step 3: Attention within window
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Attention within Window', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(mask(QK^T / √d)) · V' });
  y += 58;

  drawAttentionHeatmap(s3, cx - 80, y, seqLen, 'sliding', displayWindow);
  y += 190;

  // Step 4: Output
  const s4 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 130, y, 260, 42, 'Step 4 — Output Projection', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s4 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s4 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  lbl(g, cx, y, `Complexity: O(seq × window) = O(${seqLen} × ${windowSize}) instead of O(seq²)`, { size: 10, color: '#16a34a', weight: '600' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Project input to Q/K/V, each [batch, ${seqLen}, ${dModel}]. Three weight matrices of shape [${dModel}, ${dModel}] add ${fmtNum(3 * dModel * dModel)} parameters.`,
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Sliding Window Mask', shortLabel: 'Window Mask',
      formula: `attend to [i-${windowSize}, i]`,
      explanation: `Each query position i attends only to keys within the previous ${windowSize} positions. Positions outside the window are masked to -inf, cutting the effective attention length from seq² to seq × window.`,
      code: { title: 'Window Mask', lines: [`window_size = ${windowSize}`, 'mask = (i - j).abs() <= window_size', 'scores.masked_fill_(~mask, -inf)'] },
      svgGroup: 'step-attn-window', color: '#d97706', fill: '#fef3c7' },
    { id: 3, label: 'Attention within Window', shortLabel: 'Attention',
      formula: 'A = softmax(mask(QK^T / √d)) · V',
      explanation: `Compute per-head attention scores [${seqLen}, ${seqLen}], apply the sliding-window mask, softmax, and multiply by V. Only O(${seqLen} × ${windowSize}) non-masked entries contribute materially.`,
      code: { title: 'Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'scores = scores.masked_fill(~window_mask, -inf)', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate all heads and apply W_o [${dModel}, ${dModel}], producing output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Sparse ────────────────────────────────────────────────────────────────────

function renderSparse(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const localWindow = Math.min(128, Math.floor(seqLen / 8));
  let y = 28;

  y = drawHeader(g, cx, y, 'Sparse Attention (BigBird/Longformer)', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  const s2 = g.append('g').attr('class', 'step-node step-attn-sparse').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Build Sparse Pattern', { step: 2, fill: '#fef3c7', stroke: '#d97706', formula: 'local + global + random' });
  y += 58;

  // Three sub-patterns
  drawMaskPattern(s2, cx - 230, y, seqLen, 'sliding', 2);
  lbl(s2 as Sel, cx - 185, y + 160, 'Local', { size: 8, color: '#666' });

  const globalGroup = s2.append('g');
  const globalSize = Math.min(seqLen, 12);
  const globalCell = Math.min(10, 120 / globalSize);
  for (let r = 0; r < globalSize; r++) {
    for (let c = 0; c < globalSize; c++) {
      const allowed = c < 2 || r < 2;
      globalGroup.append('rect')
        .attr('x', cx - 70 + c * globalCell)
        .attr('y', y + r * globalCell)
        .attr('width', globalCell).attr('height', globalCell)
        .attr('fill', allowed ? '#22c55e' : '#fee2e2')
        .attr('stroke', '#e0e0e0').attr('stroke-width', 0.3);
    }
  }
  lbl(globalGroup as Sel, cx - 10, y + globalSize * globalCell + 14, 'Global', { size: 8, color: '#666' });

  drawMaskPattern(s2, cx + 90, y, seqLen, 'sparse');
  lbl(s2 as Sel, cx + 150, y + 160, 'Combined', { size: 8, color: '#666' });
  y += 180;

  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Sparse Attention', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(sparse(QK^T) / √d) · V' });
  y += 58;
  drawAttentionHeatmap(s3, cx - 80, y, seqLen, 'sparse');
  y += 190;

  const s4 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 130, y, 260, 42, 'Step 4 — Output Projection', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s4 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s4 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Project input to Q/K/V, each [batch, ${seqLen}, ${dModel}]. Total projection parameters: ${fmtNum(3 * dModel * dModel)}.`,
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Build Sparse Pattern', shortLabel: 'Sparse Pattern',
      formula: 'local + global + random',
      explanation: `Sparse attention combines a local sliding window (w=${localWindow}), a few global tokens that attend to/from all positions, and sampled random long-range edges. The union avoids the dense O(seq²) cost while preserving receptive field.`,
      code: { title: 'Sparse Pattern', lines: [`local_window = ${localWindow}`, 'global_mask = i < n_global or j < n_global', 'random_mask = sample_random_pairs', 'mask = local | global | random'] },
      svgGroup: 'step-attn-sparse', color: '#d97706', fill: '#fef3c7' },
    { id: 3, label: 'Sparse Attention', shortLabel: 'Sparse Attention',
      formula: 'A = softmax(sparse(QK^T) / √d) · V',
      explanation: `Compute attention scores [${seqLen}, ${seqLen}], mask out all disallowed positions, then softmax and multiply by V. Effective non-zero entries are proportional to the sparse pattern size, typically O(seq) or O(seq log seq).`,
      code: { title: 'Sparse Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'scores = scores.masked_fill(~sparse_mask, -inf)', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate heads and apply W_o [${dModel}, ${dModel}], yielding output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Ring Attention ────────────────────────────────────────────────────────────

function renderRing(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const P = 4;
  const localSeq = Math.floor(seqLen / P);
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'Ring Attention (Distributed)', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  P=${P} ranks  local_seq=${localSeq}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: Sequence split
  const s1 = g.append('g').attr('class', 'step-node step-attn-ring').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Split Sequence across Ranks', { step: 1, fill: '#dbeafe', stroke: '#2563eb', formula: `seq_len / ${P} = ${localSeq}` });
  y += 58;

  for (let rank = 0; rank < P; rank++) {
    const rx = cx - (P * 90) / 2 + rank * 90 + 45;
    drawTensor(s1 as Sel, rx - 35, y, 70, 28, `rank ${rank}`, '#dbeafe', '#2563eb');
    lbl(s1 as Sel, rx, y + 42, `${rank * localSeq}:${(rank + 1) * localSeq}`, { size: 7, color: '#666' });
  }
  y += 60;

  // Step 2: Local QKV
  const s2 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Local Q/K/V Projection per Rank', { step: 2, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q/K/V = local_x · W_q/k/v' });
  y += 58;

  for (let rank = 0; rank < P; rank++) {
    const rx = cx - (P * 80) / 2 + rank * 80 + 40;
    drawMatrixBlock(s2 as Sel, rx - 20, y, { width: 40, height: 40, label: 'W', sublabel: '', fill: '#dbeafe', stroke: '#2563eb' });
    lbl(s2 as Sel, rx, y + 55, `[${localSeq}, ${dModel}]`, { size: 6, color: '#888' });
  }
  y += 68;

  // Step 3: Ring pass
  const s3 = g.append('g').attr('class', 'step-node step-attn-ring').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Ring-Pass K/V Blocks', { step: 3, fill: '#fef3c7', stroke: '#d97706', formula: 'P2P rotate K/V, accumulate partial outputs' });
  y += 58;

  for (let rank = 0; rank < P; rank++) {
    const rx = cx - (P * 80) / 2 + rank * 80 + 40;
    drawTensor(s3 as Sel, rx - 20, y, 40, 24, `KV${rank}`, '#fef3c7', '#d97706');
    if (rank < P - 1) {
      g.append('line')
        .attr('x1', rx + 25).attr('y1', y + 12)
        .attr('x2', rx + 55).attr('y2', y + 12)
        .attr('stroke', '#d97706').attr('stroke-width', 1.5)
        .attr('marker-end', 'url(#attn-arrow-orange)');
    } else {
      // wrap around arrow (curved)
      g.append('path')
        .attr('d', `M ${rx + 25} ${y + 12} Q ${cx} ${y + 50} ${cx - (P * 80) / 2 + 15} ${y + 12}`)
        .attr('fill', 'none').attr('stroke', '#d97706').attr('stroke-width', 1.5)
        .attr('stroke-dasharray', '4,4');
    }
  }
  lbl(s3 as Sel, cx, y + 50, `${P - 1} rotations until each rank sees all K/V`, { size: 9, color: '#666' });
  y += 75;

  // Step 4: Local attention + accumulate
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 160, y, 320, 42, 'Step 4 — Local Attention + Accumulate', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'O_rank += softmax(Q_local @ K_pass^T / √d) · V_pass' });
  y += 58;

  const q4 = matrixBBox(cx - 100, y, 4, 4, 12);
  const kt4 = matrixBBox(cx - 10, y, 4, 4, 12);
  const o4 = matrixBBox(cx + 90, y, 4, 4, 12);
  drawSmallMatrix(s4, q4.x, q4.y, 4, 4, 12, 'Q_local', '#dbeafe', `[${localSeq}, ${dHead}]`);
  lbl(s4 as Sel, cx - 35, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s4, kt4.x, kt4.y, 4, 4, 12, 'K_pass^T', '#fef3c7', `[${dHead}, ${localSeq}]`);
  arrowH(s4 as Sel, kt4.right + 4, o4.x - 4, y + 24, '#9333ea');
  drawSmallMatrix(s4, o4.x, o4.y, 4, 4, 12, 'O_partial', '#f3e8ff', `[${localSeq}, ${dHead}]`);
  lbl(s4 as Sel, cx + 90, o4.bottom + 24, '+= accumulate', { size: 8, color: '#9333ea' });
  y += 90;

  // Step 5: Allreduce
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 140, y, 280, 42, 'Step 5 — AllReduce + Output', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'allreduce(O) → Concat → W_o' });
  y += 58;
  drawTensor(s5 as Sel, cx - 50, y, 100, 28, 'allreduce', '#ffedd5', '#ea580c');
  drawTensor(s5 as Sel, cx + 70, y + 5, 100, 26, `out`, '#ffedd5', '#ea580c');
  lbl(s5 as Sel, cx + 120, y + 34, `[b, ${seqLen}, ${dModel}]`, { size: 8, color: '#888' });
  y += 65;

  const steps: AttnStep[] = [
    { id: 1, label: 'Split Sequence across Ranks', shortLabel: 'Split',
      formula: `seq_len / ${P} = ${localSeq}`,
      explanation: `Sequence is split into ${P} contiguous chunks of ${localSeq} tokens, each placed on a different GPU rank.`,
      code: { title: 'Split', lines: [`local_seq_len = seq_len // ${P}`, 'x_local = x[rank * local_seq_len : (rank+1) * local_seq_len]'] },
      svgGroup: 'step-attn-ring', color: '#2563eb', fill: '#dbeafe' },
    { id: 2, label: 'Local Q/K/V Projection', shortLabel: 'Local QKV',
      formula: 'Q/K/V = local_x · W_q/k/v',
      explanation: `Each rank computes Q/K/V for its local chunk [batch, ${localSeq}, ${dModel}] using the shared projection weights.`,
      code: { title: 'Local QKV', lines: ['q_local = x_local @ Wq', 'k_local = x_local @ Wk', 'v_local = x_local @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 3, label: 'Ring-Pass K/V Blocks', shortLabel: 'Ring Pass',
      formula: 'P2P rotate K/V',
      explanation: `K/V blocks rotate through ranks via P2P send/recv. After ${P - 1} rotations each rank has seen all K/V blocks, achieving full attention without holding the full [${seqLen}, ${dModel}] cache on any one GPU.`,
      code: { title: 'Ring Pass', lines: ['for step in range(P - 1):', '  send K/V to next rank', '  recv K/V from prev rank', '  accumulate local attention'] },
      svgGroup: 'step-attn-ring', color: '#d97706', fill: '#fef3c7' },
    { id: 4, label: 'Local Attention + Accumulate', shortLabel: 'Accumulate',
      formula: 'O += softmax(Q_local @ K_pass^T / √d) · V_pass',
      explanation: `Each rank computes local attention with the passing K/V block and accumulates partial output [${localSeq}, ${dHead}]. The full O(seq²) attention is decomposed into P chunks.`,
      code: { title: 'Accumulate', lines: ['scores = (q_local @ k_pass.T) / sqrt(d_head)', 'attn = softmax(scores)', 'o_local += attn @ v_pass'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'AllReduce + Output', shortLabel: 'Output',
      formula: 'allreduce(O) → W_o',
      explanation: `Partial outputs from all ranks are combined via allreduce, concatenated across heads, and projected to [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['o = allreduce(o_local)', 'return self.Wo(concat(o))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Flash Attention ───────────────────────────────────────────────────────────

function renderFlash(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const blockSize = 64;
  let y = 28;

  y = drawHeader(g, cx, y, 'Flash Attention (IO-Aware)', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  block_size=${blockSize}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: Tile into SRAM
  const s2 = g.append('g').attr('class', 'step-node step-attn-tile').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Tile into SRAM Blocks', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `B_r × B_c = ${blockSize} × ${blockSize}` });
  y += 58;

  // Q tiles
  lbl(s2 as Sel, cx - 130, y, 'Q tiles', { size: 9, weight: '600', color: '#2563eb' });
  for (let i = 0; i < 4; i++) {
    drawTensor(s2 as Sel, cx - 150 + i * 60, y + 12, 45, 20, `Q_${i}`, '#dbeafe', '#2563eb');
  }
  lbl(s2 as Sel, cx + 125, y + 24, `[${blockSize}, ${dHead}]`, { size: 7, color: '#888' });
  y += 50;

  // K/V tiles
  lbl(s2 as Sel, cx - 130, y, 'K/V tiles', { size: 9, weight: '600', color: '#16a34a' });
  for (let i = 0; i < 4; i++) {
    drawTensor(s2 as Sel, cx - 150 + i * 60, y + 12, 45, 20, `K/V_${i}`, '#dcfce7', '#16a34a');
  }
  lbl(s2 as Sel, cx + 125, y + 24, `[${blockSize}, ${dHead}]`, { size: 7, color: '#888' });
  y += 55;

  // Step 3: Block-level QK^T
  const s3 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Block-Level QK^T + Mask', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'S_ij = Q_i @ K_j^T / √d' });
  y += 58;

  const q3 = matrixBBox(cx - 100, y, 4, 4, 13);
  const kt3 = matrixBBox(cx - 25, y, 4, 4, 13);
  const s3out = matrixBBox(cx + 70, y, 4, 4, 13);
  drawSmallMatrix(s3, q3.x, q3.y, 4, 4, 13, 'Q_i', '#dbeafe', `[${blockSize}, ${dHead}]`);
  lbl(s3 as Sel, cx - 40, y + 26, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, kt3.x, kt3.y, 4, 4, 13, 'K_j^T', '#dcfce7', `[${dHead}, ${blockSize}]`);
  arrowH(s3 as Sel, kt3.right + 4, s3out.x - 4, y + 26, '#9333ea');
  drawSmallMatrix(s3, s3out.x, s3out.y, 4, 4, 13, 'S_ij', '#f3e8ff', `[${blockSize}, ${blockSize}]`);
  y += 80;

  // Step 4: Online softmax
  const s4 = g.append('g').attr('class', 'step-node step-attn-online').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 170, y, 340, 42, 'Step 4 — Online Softmax (Running Max/Sum)', { step: 4, fill: '#fef3c7', stroke: '#d97706', formula: 'm_new, l_new, O_rescaled' });
  y += 58;

  drawTensor(s4 as Sel, cx - 130, y, 90, 28, 'running max', '#fef3c7', '#d97706');
  drawTensor(s4 as Sel, cx - 20, y, 90, 28, 'running sum', '#fef3c7', '#d97706');
  drawTensor(s4 as Sel, cx + 90, y, 90, 28, 'O partial', '#fef3c7', '#d97706');
  lbl(s4 as Sel, cx + 150, y + 14, 'per row', { size: 7, color: '#888' });
  y += 50;

  // Step 5: Rescale and accumulate
  const s5 = g.append('g').attr('class', 'step-node step-attn-accum').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 160, y, 320, 42, 'Step 5 — Rescale + Accumulate Outputs', { step: 5, fill: '#f3e8ff', stroke: '#9333ea', formula: 'O_new = rescale(O_old) + P_ij @ V_j' });
  y += 58;

  const p5 = matrixBBox(cx - 100, y, 4, 4, 13);
  const v5 = matrixBBox(cx - 25, y, 4, 4, 13);
  const o5 = matrixBBox(cx + 70, y, 4, 4, 13);
  drawSmallMatrix(s5, p5.x, p5.y, 4, 4, 13, 'P_ij', '#fef3c7', `[${blockSize}, ${blockSize}]`);
  lbl(s5 as Sel, cx - 40, y + 26, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s5, v5.x, v5.y, 4, 4, 13, 'V_j', '#dcfce7', `[${blockSize}, ${dHead}]`);
  arrowH(s5 as Sel, v5.right + 4, o5.x - 4, y + 26, '#9333ea');
  drawSmallMatrix(s5, o5.x, o5.y, 4, 4, 13, 'O_i', '#f3e8ff', `[${blockSize}, ${dHead}]`);
  y += 80;

  // Step 6: Output
  const s6 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '6');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s6 as Sel, cx - 150, y, 300, 42, 'Step 6 — Final Output Projection', { step: 6, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s6 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s6 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  lbl(g, cx, y, 'Key benefit: no materialization of full [seq, seq] attention matrix in HBM', { size: 10, color: '#16a34a', weight: '600' });
  y += 24;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Project input to Q/K/V, each [batch, ${seqLen}, ${dModel}]. Parameters: ${fmtNum(3 * dModel * dModel)}.`,
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Tile into SRAM', shortLabel: 'Tiling',
      formula: `B_r × B_c = ${blockSize} × ${blockSize}`,
      explanation: `Flash Attention tiles Q/K/V into SRAM blocks of size ${blockSize}×${dHead}. Each block fits in fast on-chip memory, avoiding HBM reads/writes for the full [${seqLen}, ${seqLen}] attention matrix.`,
      code: { title: 'Tiling', lines: [`block_size = ${blockSize}`, 'for Q_block in tiled(Q):', '  for K_block, V_block in tiled(K, V):', '    compute in SRAM'] },
      svgGroup: 'step-attn-tile', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Block-Level QK^T', shortLabel: 'Block QK^T',
      formula: 'S_ij = Q_i @ K_j^T / √d',
      explanation: `Compute attention scores block by block inside SRAM: [${blockSize}, ${dHead}] @ [${dHead}, ${blockSize}] = [${blockSize}, ${blockSize}]. Causal masking is applied per block.`,
      code: { title: 'Block Scores', lines: ['S_ij = (Q_i @ K_j.T) / sqrt(d_head)', 'S_ij = apply_causal_mask(S_ij)'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Online Softmax', shortLabel: 'Online Softmax',
      formula: 'm_new, l_new',
      explanation: 'Track per-row running maximum m and normalizing sum l across K/V blocks. This keeps softmax numerically stable without materializing the full score matrix.',
      code: { title: 'Online Softmax', lines: ['m_new = max(m_old, rowmax(S_ij))', 'l_new = exp(m_old-m_new)*l_old + rowsum(exp(S_ij-m_new))'] },
      svgGroup: 'step-attn-online', color: '#d97706', fill: '#fef3c7' },
    { id: 5, label: 'Rescale + Accumulate', shortLabel: 'Accumulate',
      formula: 'O_new = rescale(O_old) + P_ij @ V_j',
      explanation: `Rescale previous partial output with the updated running statistics, then add the contribution from the current V block [${blockSize}, ${dHead}].`,
      code: { title: 'Accumulate', lines: ['O_old = (l_old / l_new) * exp(m_old - m_new) * O_old', 'O_new = O_old + (1/l_new) * exp(S_ij - m_new) @ V_j'] },
      svgGroup: 'step-attn-accum', color: '#9333ea', fill: '#f3e8ff' },
    { id: 6, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate heads and apply W_o [${dModel}, ${dModel}], producing output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Paged Attention ───────────────────────────────────────────────────────────

function renderPaged(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  const pageSize = 16;
  const nPages = Math.ceil(seqLen / pageSize);
  let y = 28;

  y = drawHeader(g, cx, y, 'PagedAttention (vLLM)', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  page_size=${pageSize}  n_pages=${nPages}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: Pack K/V into pages
  const s2 = g.append('g').attr('class', 'step-node step-attn-paged').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 160, y, 320, 42, 'Step 2 — Pack K/V into Pages', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: `page_size=${pageSize}` });
  y += 58;

  for (let p = 0; p < Math.min(nPages, 6); p++) {
    drawTensor(s2 as Sel, cx - 150 + p * 55, y, 45, 22, `P${p}`, '#dbeafe', '#2563eb');
  }
  if (nPages > 6) {
    lbl(s2 as Sel, cx - 150 + 6 * 55 + 8, y + 11, `...${nPages - 6} more`, { size: 7, color: '#888', anchor: 'start' });
  }
  lbl(s2 as Sel, cx, y + 42, `page shape: [${pageSize}, n_heads, ${dHead}]`, { size: 8, color: '#666' });
  y += 55;

  // Step 3: Block table
  const s3 = g.append('g').attr('class', 'step-node step-attn-lookup').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 160, y, 320, 42, 'Step 3 — Block Table (Logical → Physical)', { step: 3, fill: '#fef3c7', stroke: '#d97706', formula: 'block_table[logical_pos] = physical_page' });
  y += 58;

  const blockTable = [3, 1, 4, 0, 5, 2];
  lbl(s3 as Sel, cx - 160, y, 'logical:', { size: 8, color: '#666' });
  lbl(s3 as Sel, cx - 160, y + 14, 'physical:', { size: 8, color: '#666' });
  for (let i = 0; i < Math.min(nPages, 6); i++) {
    lbl(s3 as Sel, cx - 110 + i * 50, y, `${i}`, { size: 8, color: '#2563eb' });
    drawTensor(s3 as Sel, cx - 130 + i * 50, y + 10, 35, 18, `${blockTable[i]}`, '#fef3c7', '#d97706');
  }
  y += 50;

  // Step 4: Attention via block lookup
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 160, y, 320, 42, 'Step 4 — Attention via Block Table Lookup', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'Q @ K[block_table]^T' });
  y += 58;

  const q4 = matrixBBox(cx - 80, y, 4, 5, 12);
  const kt4 = matrixBBox(cx + 40, y, 5, 4, 12);
  drawSmallMatrix(s4, q4.x, q4.y, 4, 5, 12, 'Q', '#dbeafe', `[1, ${dHead}]`);
  lbl(s4 as Sel, cx + 15, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s4, kt4.x, kt4.y, 5, 4, 12, 'K^T', '#fef3c7', `[${dHead}, ${pageSize}]`);
  arrowH(s4 as Sel, kt4.right + 4, kt4.right + 34, y + 24, '#9333ea');
  drawTensor(s4 as Sel, kt4.right + 40, y + 8, 50, 32, 'score', '#f3e8ff', '#9333ea');
  y += 90;

  // Step 5: Output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Project input to Q/K/V, each [batch, ${seqLen}, ${dModel}]. Parameters: ${fmtNum(3 * dModel * dModel)}.`,
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Pack K/V into Pages', shortLabel: 'Pack Pages',
      formula: `page_size=${pageSize}`,
      explanation: `KV cache is stored as ${nPages} fixed-size pages of ${pageSize} tokens. Each page holds [${pageSize}, n_heads, ${dHead}] values and can be allocated non-contiguously, reducing fragmentation.`,
      code: { title: 'Pack', lines: [`pages = k.view(-1, ${pageSize}, n_heads, d_head)  # ${nPages} pages`] },
      svgGroup: 'step-attn-paged', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Block Table', shortLabel: 'Block Table',
      formula: 'block_table[logical_pos] = physical_page',
      explanation: 'A per-sequence block table maps logical token positions to physical page indices, similar to virtual memory. Multiple sequences can share physical pages for copy-on-write beam search.',
      code: { title: 'Block Table', lines: ['block_table = allocate_pages(seq_len)', 'page_idx = block_table[token_pos // page_size]'] },
      svgGroup: 'step-attn-lookup', color: '#d97706', fill: '#fef3c7' },
    { id: 4, label: 'Attention via Block Lookup', shortLabel: 'Block Lookup',
      formula: 'Q @ K[block_table]^T',
      explanation: `During attention the lookup gathers K/V pages on demand. For decoding, a single query vector [1, ${dHead}] is scored against a page of keys [${pageSize}, ${dHead}], then repeated for all pages in the block table.`,
      code: { title: 'Lookup', lines: ['for page in block_table:', '  k, v = physical_kv_cache[page]', '  compute attention'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate heads and apply W_o [${dModel}, ${dModel}], yielding output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Linear Attention ──────────────────────────────────────────────────────────

function renderLinear(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'Linear Attention', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection + head split
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 160, y, 320, 42, 'Step 1 — Q/K/V Projection + Head Split', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q, K, V = xW_q/k/v, reshape to heads' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dHead}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dHead}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dHead}]`, '#dbeafe', '#2563eb');

  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: Feature maps
  const s2 = g.append('g').attr('class', 'step-node step-attn-phi').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 150, y, 300, 42, 'Step 2 — Apply Feature Maps φ(Q), φ(K)', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: 'φ(x) = elu(x) + 1' });
  y += 58;

  const qPhi = matrixBBox(cx - 120, y, 5, 4, 12);
  const phiQ = matrixBBox(cx + 10, y, 5, 4, 12);
  drawSmallMatrix(s2, qPhi.x, qPhi.y, 5, 4, 12, 'Q', '#dbeafe', `[${seqLen}, ${dHead}]`);
  arrowH(s2 as Sel, qPhi.right + 4, phiQ.x - 4, y + 24, '#2563eb');
  lbl(s2 as Sel, cx - 32, y + 12, 'φ(·)', { size: 9, color: '#2563eb', weight: '600' });
  drawSmallMatrix(s2, phiQ.x, phiQ.y, 5, 4, 12, 'φ(Q)', '#dbeafe', `[${seqLen}, ${dHead}]`);
  y += 80;

  // Step 3: Matrix multiplication reorder
  const s3 = g.append('g').attr('class', 'step-node step-attn-linear').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 170, y, 340, 42, 'Step 3 — Linear Complexity: φ(Q)@(φ(K)^T@V)', { step: 3, fill: '#f3e8ff', stroke: '#9333ea', formula: 'φ(Q) @ (φ(K)^T @ V)' });
  y += 58;

  lbl(s3 as Sel, cx - 160, y, 'Standard:', { size: 9, weight: '600', color: '#666' });
  lbl(s3 as Sel, cx - 60, y, `(Q @ K^T) @ V  →  O(${seqLen}²)`, { size: 9, font: 'monospace', color: '#666' });
  y += 20;
  lbl(s3 as Sel, cx - 160, y, 'Linear:', { size: 9, weight: '600', color: '#16a34a' });
  lbl(s3 as Sel, cx - 60, y, `φ(Q) @ (φ(K)^T @ V)  →  O(${seqLen})`, { size: 9, font: 'monospace', color: '#16a34a' });
  y += 30;

  const kT3 = matrixBBox(cx - 130, y, 4, 4, 12);
  const v3 = matrixBBox(cx - 60, y, 4, 3, 12);
  const kv3 = matrixBBox(cx + 50, y, 4, 3, 12);
  drawSmallMatrix(s3, kT3.x, kT3.y, 4, 4, 12, 'φ(K)^T', '#dbeafe', `[${dHead}, ${seqLen}]`);
  lbl(s3 as Sel, kT3.right + 6, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s3, v3.x, v3.y, 4, 3, 12, 'V', '#dcfce7', `[${seqLen}, ${dHead}]`);
  arrowH(s3 as Sel, v3.right + 4, kv3.x - 4, y + 20, '#9333ea');
  drawSmallMatrix(s3, kv3.x, kv3.y, 4, 3, 12, 'KV', '#f3e8ff', `[${dHead}, ${dHead}]`);
  y += 70;

  // Step 4: Multiply by Q
  const s4 = g.append('g').attr('class', 'step-node step-attn-weighted').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 42, 'Step 4 — Multiply by φ(Q)', { step: 4, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = φ(Q) @ KV' });
  y += 58;

  const phiQ4 = matrixBBox(cx - 100, y, 5, 4, 12);
  const kv4 = matrixBBox(cx - 20, y, 4, 3, 12);
  const out4 = matrixBBox(cx + 80, y, 5, 3, 12);
  drawSmallMatrix(s4, phiQ4.x, phiQ4.y, 5, 4, 12, 'φ(Q)', '#dbeafe', `[${seqLen}, ${dHead}]`);
  lbl(s4 as Sel, phiQ4.right + 6, y + 24, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s4, kv4.x, kv4.y, 4, 3, 12, 'KV', '#f3e8ff', `[${dHead}, ${dHead}]`);
  arrowH(s4 as Sel, kv4.right + 4, out4.x - 4, y + 20, '#ea580c');
  drawSmallMatrix(s4, out4.x, out4.y, 5, 3, 12, 'out', '#ffedd5', `[${seqLen}, ${dHead}]`);
  y += 75;

  // Step 5: Output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection + Head Split', shortLabel: 'QKV',
      formula: 'Q, K, V = xW_q/k/v',
      explanation: `Project input to Q/K/V with three [${dModel}, ${dModel}] matrices, then reshape into per-head tensors [batch, n_heads, ${seqLen}, ${dHead}].`,
      code: { title: 'QKV', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv', 'q, k, v = split_heads(q, k, v)'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Feature Maps', shortLabel: 'Feature Maps',
      formula: 'φ(x) = elu(x) + 1',
      explanation: 'Apply element-wise positive feature map φ to Q and K so that the kernel trick holds: φ(q)^T φ(k) ≈ exp(q^T k). This allows the softmax approximation that enables linear complexity.',
      code: { title: 'Feature Maps', lines: ['phi = lambda x: F.elu(x) + 1', 'q = phi(q)', 'k = phi(k)'] },
      svgGroup: 'step-attn-phi', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'Reorder Multiplication', shortLabel: 'Linear',
      formula: 'φ(Q) @ (φ(K)^T @ V)',
      explanation: `First compute KV = φ(K)^T @ V: [${dHead}, ${seqLen}] @ [${seqLen}, ${dHead}] = [${dHead}, ${dHead}]. This is O(seq × d²) and needs no attention matrix. Standard attention is O(seq²).`,
      code: { title: 'Linear', lines: [`KV = k.T @ v  # [${dHead}, ${dHead}]`, `# Complexity: O(${seqLen} × ${dHead}²)`] },
      svgGroup: 'step-attn-linear', color: '#9333ea', fill: '#f3e8ff' },
    { id: 4, label: 'Multiply by φ(Q)', shortLabel: 'Q @ KV',
      formula: 'out = φ(Q) @ KV',
      explanation: `Multiply each query [${seqLen}, ${dHead}] by the precomputed KV matrix [${dHead}, ${dHead}], yielding output [${seqLen}, ${dHead}] per head without any O(seq²) tensor.`,
      code: { title: 'Output', lines: [`out = q @ KV  # [${seqLen}, ${dHead}]`] },
      svgGroup: 'step-attn-weighted', color: '#ea580c', fill: '#ffedd5' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate heads and apply W_o [${dModel}, ${dModel}], producing output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── MLA ───────────────────────────────────────────────────────────────────────

function renderMLA(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const latentDim = Math.floor(dModel / 4);
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'MLA (DeepSeek Latent Attention)', `d_model=${dModel}  latent_dim=${latentDim}  n_heads=${nHeads}  d_head=${dHead}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: Q projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 160, y, 320, 42, 'Step 1 — Q Projection (full dim)', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: `Q = x · W_q  [${dModel}→${dModel}]` });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 50, y, { width: 60, height: 60, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  const wqBox = { right: cx - 50 + 60 };
  arrowH(s1 as Sel, wqBox.right + 4, wqBox.right + 40, y + 30, '#2563eb');
  drawTensor(s1 as Sel, wqBox.right + 46, y + 12, 100, 28, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  y += 90;

  // Step 2: Compress K/V to latent
  const s2 = g.append('g').attr('class', 'step-node step-attn-compress').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 170, y, 340, 42, 'Step 2 — Compress K/V to Latent', { step: 2, fill: '#f3e8ff', stroke: '#9333ea', formula: `c = x · W_down  [${dModel}→${latentDim}]` });
  y += 58;

  const wDown = { x: cx - 50, right: cx - 50 + 60 };
  drawMatrixBlock(s2 as Sel, wDown.x, y, { width: 60, height: 60, label: 'W_down', sublabel: `[${dModel}, ${latentDim}]`, fill: '#f3e8ff', stroke: '#9333ea' });
  arrowH(s2 as Sel, wDown.right + 4, wDown.right + 40, y + 30, '#9333ea');
  drawTensor(s2 as Sel, wDown.right + 46, y + 14, 115, 28, `c [b, ${seqLen}, ${latentDim}]`, '#f3e8ff', '#9333ea');
  lbl(s2 as Sel, wDown.right + 110, y + 56, `${Math.round(dModel / latentDim)}× smaller KV cache`, { size: 8, color: '#9333ea', weight: '600' });
  y += 90;

  // Step 3: Decompress to K/V
  const s3 = g.append('g').attr('class', 'step-node step-attn-decompress').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 170, y, 340, 42, 'Step 3 — Decompress Latent to K/V', { step: 3, fill: '#dbeafe', stroke: '#2563eb', formula: `K/V = c · W_up  [${latentDim}→${dModel}]` });
  y += 58;

  const cBox = matrixBBox(cx - 140, y, 3, 5, 12);
  drawSmallMatrix(s3, cBox.x, cBox.y, 3, 5, 12, 'c', '#f3e8ff', `[${seqLen}, ${latentDim}]`);
  arrowH(s3 as Sel, cBox.right + 4, cBox.right + 30, y + 18, '#2563eb');
  drawMatrixBlock(s3 as Sel, cBox.right + 36, y, { width: 50, height: 60, label: 'W_up', sublabel: `[${latentDim}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  const wUpRight = cBox.right + 36 + 50;
  arrowH(s3 as Sel, wUpRight + 4, wUpRight + 30, y + 18, '#2563eb');
  drawTensor(s3 as Sel, wUpRight + 36, y + 4, 85, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s3 as Sel, wUpRight + 36, y + 34, 85, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  y += 90;

  // Step 4: Split heads
  const s4 = g.append('g').attr('class', 'step-node step-attn-split').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 140, y, 280, 42, 'Step 4 — Split into Heads', { step: 4, fill: '#dbeafe', stroke: '#2563eb', formula: `[batch, ${nHeads}, seq, ${dHead}]` });
  y += 58;
  y += drawHeadSplit(s4, cx, y, nHeads, dHead, seqLen);

  // Step 5: Causal attention
  const s5 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 160, y, 320, 42, 'Step 5 — Causal Attention', { step: 5, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax(QK^T / √d_head) · V' });
  y += 58;

  const q5 = matrixBBox(cx - 130, y, 5, 5, 12);
  const kt5 = matrixBBox(cx - 30, y, 5, 5, 12);
  const a5 = matrixBBox(cx + 80, y, 5, 5, 12);
  drawSmallMatrix(s5, q5.x, q5.y, 5, 5, 12, 'Q', '#dbeafe', `[${seqLen}, ${dHead}]`);
  lbl(s5 as Sel, cx - 50, y + 30, '@', { size: 12, weight: '700', color: '#666' });
  drawSmallMatrix(s5, kt5.x, kt5.y, 5, 5, 12, 'K^T', '#dbeafe', `[${dHead}, ${seqLen}]`);
  arrowH(s5 as Sel, kt5.right + 4, a5.x - 4, y + 30, '#9333ea');
  drawSmallMatrix(s5, a5.x, a5.y, 5, 5, 12, 'A', '#f3e8ff', `[${seqLen}, ${seqLen}]`);

  // causal diagonal
  s5.append('line').attr('x1', a5.x).attr('y1', a5.y)
    .attr('x2', a5.right).attr('y2', a5.bottom)
    .attr('stroke', '#ef4444').attr('stroke-width', 1).attr('stroke-dasharray', '3,3');
  y += 90;

  // Step 6: Output
  const s6 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '6');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s6 as Sel, cx - 130, y, 260, 42, 'Step 6 — Output Projection', { step: 6, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s6 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s6 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q Projection (full dim)', shortLabel: 'Q Projection',
      formula: `Q = x · W_q  [${dModel}→${dModel}]`,
      explanation: `Q is projected normally to full d_model=${dModel} using W_q [${dModel}, ${dModel}]. Unlike K/V, Q is not compressed — it does not need to be cached during inference.`,
      code: { title: 'Q', lines: [`Wq: [${dModel}, ${dModel}]`, 'q = x @ Wq'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'Compress K/V to Latent', shortLabel: 'Compress',
      formula: `c = x · W_down  [${dModel}→${latentDim}]`,
      explanation: `Both K and V are jointly compressed into a shared latent vector c [batch, seq, ${latentDim}] via W_down [${dModel}, ${latentDim}]. Only c is cached at inference time, reducing KV cache by ${Math.round(dModel / latentDim)}×.`,
      code: { title: 'Compress', lines: [`W_down: [${dModel}, ${latentDim}]`, `c = x @ W_down  # [batch, seq, ${latentDim}]`, '# Cache only c, not K/V directly'] },
      svgGroup: 'step-attn-compress', color: '#9333ea', fill: '#f3e8ff' },
    { id: 3, label: 'Decompress to K/V', shortLabel: 'Decompress',
      formula: `K/V = c · W_up  [${latentDim}→${dModel}]`,
      explanation: `During attention the latent c is up-projected by separate W_up_k and W_up_v matrices [${latentDim}, ${dModel}] to recover full-dimension K and V. In practice this can be absorbed into W_q for further optimization.`,
      code: { title: 'Decompress', lines: [`W_up_k, W_up_v: [${latentDim}, ${dModel}]`, 'k = c @ W_up_k', 'v = c @ W_up_v'] },
      svgGroup: 'step-attn-decompress', color: '#2563eb', fill: '#dbeafe' },
    { id: 4, label: 'Split into Heads', shortLabel: 'Head Split',
      formula: `[batch, ${nHeads}, seq, ${dHead}]`,
      explanation: `Reshape Q/K/V from [batch, ${seqLen}, ${dModel}] into [batch, ${nHeads}, ${seqLen}, ${dHead}] for multi-head attention.`,
      code: { title: 'Split', lines: [`q, k, v = split_heads(q, k, v, n_heads=${nHeads})`] },
      svgGroup: 'step-attn-split', color: '#2563eb', fill: '#dbeafe' },
    { id: 5, label: 'Causal Attention', shortLabel: 'Attention',
      formula: 'A = softmax(QK^T / √d_head) · V',
      explanation: `Standard causal scaled dot-product attention per head. Scores [${seqLen}, ${seqLen}] are masked causally, softmax'd, and multiplied by V to produce per-head output [${seqLen}, ${dHead}].`,
      code: { title: 'Attention', lines: ['scores = (q @ k.T) / sqrt(d_head)', 'scores = causal_mask(scores)', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 6, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate all ${nHeads} heads and apply W_o [${dModel}, ${dModel}], producing output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── RoPE + ALiBi ──────────────────────────────────────────────────────────────

function renderRoPEALiBi(g: Gsel, seqLen: number, dModel: number, nHeads: number, W: number)
  : { width: number; height: number; steps: AttnStep[] } {
  const cx = W / 2;
  const dHead = Math.floor(dModel / nHeads);
  let y = 28;

  y = drawHeader(g, cx, y, 'RoPE + ALiBi (Combined)', `d_model=${dModel}  n_heads=${nHeads}  d_head=${dHead}  seq_len=${seqLen}`);

  drawTensor(g, cx - 110, y, 220, 30, `x: [batch, ${seqLen}, ${dModel}]`, '#dcfce7', '#16a34a');
  y += 52;

  // Step 1: QKV projection
  const s1 = g.append('g').attr('class', 'step-node step-attn-qkv').attr('data-step', '1');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s1 as Sel, cx - 150, y, 300, 42, 'Step 1 — Q/K/V Projection', { step: 1, fill: '#dcfce7', stroke: '#16a34a', formula: 'Q = xW_q, K = xW_k, V = xW_v' });
  y += 58;

  drawMatrixBlock(s1 as Sel, cx - 170, y, { width: 80, height: 55, label: 'W_q', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx - 40, y, { width: 80, height: 55, label: 'W_k', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawMatrixBlock(s1 as Sel, cx + 90, y, { width: 80, height: 55, label: 'W_v', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });

  arrowDown(s1 as Sel, cx - 130, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx, y - 22, y - 2, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y - 22, y - 2, '#2563eb');

  drawTensor(s1 as Sel, cx - 170, y + 70, 80, 24, `Q [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx - 40, y + 70, 80, 24, `K [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');
  drawTensor(s1 as Sel, cx + 90, y + 70, 80, 24, `V [b, ${seqLen}, ${dModel}]`, '#dbeafe', '#2563eb');

  arrowDown(s1 as Sel, cx - 130, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx, y + 55, y + 70, '#2563eb');
  arrowDown(s1 as Sel, cx + 130, y + 55, y + 70, '#2563eb');
  y += 118;

  // Step 2: RoPE rotation
  const s2 = g.append('g').attr('class', 'step-node step-attn-rope').attr('data-step', '2');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s2 as Sel, cx - 140, y, 280, 42, 'Step 2 — RoPE Rotate Q/K', { step: 2, fill: '#dbeafe', stroke: '#2563eb', formula: 'R(θ·pos) · [q, k]' });
  y += 58;

  // 2D rotation illustration
  const planeR = 40;
  const planeCy = y + planeR + 8;
  s2.append('circle').attr('cx', cx).attr('cy', planeCy).attr('r', planeR)
    .attr('fill', 'none').attr('stroke', '#ddd').attr('stroke-width', 1);
  s2.append('line').attr('x1', cx - planeR).attr('y1', planeCy).attr('x2', cx + planeR).attr('y2', planeCy).attr('stroke', '#ddd').attr('stroke-width', 0.5);
  s2.append('line').attr('x1', cx).attr('y1', planeCy - planeR).attr('x2', cx).attr('y2', planeCy + planeR).attr('stroke', '#ddd').attr('stroke-width', 0.5);

  // original vector (blue)
  s2.append('line').attr('x1', cx).attr('y1', planeCy).attr('x2', cx + planeR * 0.7).attr('y2', planeCy - planeR * 0.3).attr('stroke', '#2563eb').attr('stroke-width', 2);
  s2.append('text').attr('x', cx + planeR * 0.7 + 4).attr('y', planeCy - planeR * 0.3 - 2).attr('font-size', 8).attr('fill', '#2563eb').text('q (pos m)');
  // rotated vector (orange)
  const angle = 0.8;
  s2.append('line').attr('x1', cx).attr('y1', planeCy).attr('x2', cx + planeR * 0.7 * Math.cos(angle)).attr('y2', planeCy - planeR * 0.7 * Math.sin(angle)).attr('stroke', '#ea580c').attr('stroke-width', 2);
  s2.append('text').attr('x', cx + planeR * 0.7 * Math.cos(angle) + 4).attr('y', planeCy - planeR * 0.7 * Math.sin(angle) - 2).attr('font-size', 8).attr('fill', '#ea580c').text('q_rot');
  // arc
  const arcGen = d3.arc().innerRadius(planeR * 0.3).outerRadius(planeR * 0.35);
  s2.append('path')
    .attr('d', arcGen({ innerRadius: planeR * 0.3, outerRadius: planeR * 0.35, startAngle: -0.4, endAngle: 0.4 }) as string)
    .attr('transform', `translate(${cx}, ${planeCy})`)
    .attr('fill', '#ea580c');

  lbl(s2 as Sel, cx, y + planeR * 2 + 20, `Rotate Q/K dimension pairs by θ_i × pos; dot(q_m, k_n) encodes relative distance (m-n)`, { size: 9, color: '#666' });
  y += planeR * 2 + 45;

  // Step 3: ALiBi bias
  const s3 = g.append('g').attr('class', 'step-node step-attn-alibi').attr('data-step', '3');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s3 as Sel, cx - 150, y, 300, 42, 'Step 3 — Add ALiBi Slope Bias', { step: 3, fill: '#dcfce7', stroke: '#16a34a', formula: 'scores += m_h · (i - j)' });
  y += 58;

  // Slope bars
  const nSlopeDisplay = Math.min(nHeads, 6);
  for (let h = 0; h < nSlopeDisplay; h++) {
    const slope = Math.pow(2, -(8 / nHeads) * (h + 1));
    const sx = cx - Math.floor(nSlopeDisplay / 2) * 60 + h * 60;
    const barH = Math.max(2, 40 * slope);
    s3.append('rect').attr('x', sx - 10).attr('y', y + 40 - barH).attr('width', 20).attr('height', barH).attr('fill', '#16a34a').attr('opacity', 0.7);
    lbl(s3 as Sel, sx, y + 55, `h${h}`, { size: 7, color: '#666' });
    lbl(s3 as Sel, sx, y + 66, slope.toFixed(3), { size: 6, color: '#888' });
  }
  lbl(s3 as Sel, cx, y + 80, `slope m_h = 2^(-8h/n_heads); bias decays further positions more strongly`, { size: 9, color: '#666' });
  y += 96;

  // Step 4: Attention
  const s4 = g.append('g').attr('class', 'step-node step-attn-attn').attr('data-step', '4');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s4 as Sel, cx - 170, y, 340, 42, 'Step 4 — Attention with RoPE + ALiBi', { step: 4, fill: '#f3e8ff', stroke: '#9333ea', formula: 'A = softmax((Q_rot K_rot^T / √d) + bias) · V' });
  y += 58;

  const qkT4 = matrixBBox(cx - 130, y, 5, 5, 12);
  const bias4 = matrixBBox(cx - 10, y, 5, 5, 12);
  const a4 = matrixBBox(cx + 110, y, 5, 5, 12);
  drawSmallMatrix(s4, qkT4.x, qkT4.y, 5, 5, 12, 'QK^T/√d', '#dbeafe', `[${seqLen}, ${seqLen}]`);
  lbl(s4 as Sel, qkT4.right + 6, y + 30, '+', { size: 14, weight: '700', color: '#666' });
  drawSmallMatrix(s4, bias4.x, bias4.y, 5, 5, 12, 'bias', '#dcfce7', `[${seqLen}, ${seqLen}]`);
  arrowH(s4 as Sel, bias4.right + 4, a4.x - 4, y + 30, '#9333ea');
  drawSmallMatrix(s4, a4.x, a4.y, 5, 5, 12, 'A', '#f3e8ff', `[${seqLen}, ${seqLen}]`);
  y += 90;

  // Step 5: Output
  const s5 = g.append('g').attr('class', 'step-node step-attn-out').attr('data-step', '5');
  arrowDown(g, cx, y - 14, y - 2);
  drawStepBox(s5 as Sel, cx - 130, y, 260, 42, 'Step 5 — Output Projection', { step: 5, fill: '#ffedd5', stroke: '#ea580c', formula: 'out = Concat(heads) · W_o' });
  y += 58;
  drawMatrixBlock(s5 as Sel, cx - 40, y, { width: 80, height: 50, label: 'W_o', sublabel: `[${dModel}, ${dModel}]`, fill: '#dbeafe', stroke: '#2563eb' });
  drawTensor(s5 as Sel, cx + 70, y + 10, 120, 28, `out [b, ${seqLen}, ${dModel}]`, '#ffedd5', '#ea580c');
  y += 80;

  const steps: AttnStep[] = [
    { id: 1, label: 'Q/K/V Projection', shortLabel: 'QKV',
      formula: 'Q = xW_q, K = xW_k, V = xW_v',
      explanation: `Project input to Q/K/V, each [batch, ${seqLen}, ${dModel}]. Parameters: ${fmtNum(3 * dModel * dModel)}.`,
      code: { title: 'Projection', lines: ['q, k, v = x @ Wq, x @ Wk, x @ Wv'] },
      svgGroup: 'step-attn-qkv', color: '#16a34a', fill: '#dcfce7' },
    { id: 2, label: 'RoPE Rotate Q/K', shortLabel: 'RoPE',
      formula: 'R(θ·pos) · [q, k]',
      explanation: `RoPE rotates consecutive Q/K dimension pairs in 2D planes by angle θ_i × position. The inner product of rotated Q and K only depends on the relative position (m-n), giving the model relative position information without extra learnable embeddings.`,
      code: { title: 'RoPE', lines: ['# theta_i = 10000^(-2i/d_head)', 'q_rot = rotate(q, theta * pos)', 'k_rot = rotate(k, theta * pos)'] },
      svgGroup: 'step-attn-rope', color: '#2563eb', fill: '#dbeafe' },
    { id: 3, label: 'ALiBi Slope Bias', shortLabel: 'ALiBi',
      formula: 'scores += m_h · (i - j)',
      explanation: `ALiBi adds a negative linear bias proportional to the distance: scores[i,j] += m_h × (i-j) where m_h = 2^(-8h/n_heads) is a head-specific slope (${nHeads} heads = ${nHeads} slopes). Farther keys are penalized more.`,
      code: { title: 'ALiBi', lines: [`m_h = 2**(-8 * h / ${nHeads})  # per head`, 'dist = i - j  # relative position', 'scores += m_h * dist'] },
      svgGroup: 'step-attn-alibi', color: '#16a34a', fill: '#dcfce7' },
    { id: 4, label: 'Attention with RoPE + ALiBi', shortLabel: 'Attention',
      formula: 'A = softmax((Q_rot K_rot^T / √d) + bias) · V',
      explanation: `Combine both: compute rotated QK^T [${seqLen}, ${seqLen}], scale by 1/√${dHead}, add ALiBi bias, softmax, multiply by V. RoPE captures relative order; ALiBi adds monotonic distance penalty.`,
      code: { title: 'Combined', lines: ['scores = (q_rot @ k_rot.T) / sqrt(d_head)', 'scores += alibi_bias', 'attn = softmax(scores)', 'out = attn @ v'] },
      svgGroup: 'step-attn-attn', color: '#9333ea', fill: '#f3e8ff' },
    { id: 5, label: 'Output Projection', shortLabel: 'Output',
      formula: 'out = Concat(heads) · W_o',
      explanation: `Concatenate heads and apply W_o [${dModel}, ${dModel}], producing output [batch, ${seqLen}, ${dModel}].`,
      code: { title: 'Output', lines: ['return self.Wo(concat(heads))'] },
      svgGroup: 'step-attn-out', color: '#ea580c', fill: '#ffedd5' },
  ];

  return { width: W, height: y, steps };
}

// ── Arrow marker definitions ──────────────────────────────────────────────────

function addArrowMarkerDef(g: Gsel, id: string, color: string): void {
  const defs = g.selectAll('defs').empty() ? g.append('defs') : g.select('defs');
  defs.append('marker')
    .attr('id', id)
    .attr('viewBox', '0 -5 10 10')
    .attr('refX', 8)
    .attr('refY', 0)
    .attr('markerWidth', 6)
    .attr('markerHeight', 6)
    .attr('orient', 'auto')
    .append('path')
    .attr('d', 'M0,-5L10,0L0,5')
    .attr('fill', color);
}

// ── Main Entry ────────────────────────────────────────────────────────────────

export function renderAttentionDetailed(
  g: Sel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph,
): { width: number; height: number; steps: AttnStep[] } {
  const variant = String(params.variant ?? 'standard');
  const seqLen = Number(params.seq_len ?? 128);
  const dModel = Number(params.d_model ?? 512);
  const nHeads = Number(params.n_heads ?? 8);
  const W = 800;

  addArrowMarkerDef(g as Gsel, 'attn-arrow-orange', '#d97706');

  switch (variant) {
    case 'gqa':
      return renderGQAMQA(g as Gsel, seqLen, dModel, nHeads, W, false);
    case 'mqa':
      return renderGQAMQA(g as Gsel, seqLen, dModel, nHeads, W, true);
    case 'cross-attention':
      return renderCrossAttention(g as Gsel, seqLen, dModel, nHeads, W);
    case 'bidirectional':
      return renderBidirectional(g as Gsel, seqLen, dModel, nHeads, W);
    case 'sliding-window':
      return renderSlidingWindow(g as Gsel, seqLen, dModel, nHeads, W);
    case 'sparse':
      return renderSparse(g as Gsel, seqLen, dModel, nHeads, W);
    case 'ring':
      return renderRing(g as Gsel, seqLen, dModel, nHeads, W);
    case 'flash':
      return renderFlash(g as Gsel, seqLen, dModel, nHeads, W);
    case 'paged':
      return renderPaged(g as Gsel, seqLen, dModel, nHeads, W);
    case 'linear-attention':
      return renderLinear(g as Gsel, seqLen, dModel, nHeads, W);
    case 'mla':
      return renderMLA(g as Gsel, seqLen, dModel, nHeads, W);
    case 'rope_alibi':
      return renderRoPEALiBi(g as Gsel, seqLen, dModel, nHeads, W);
    default:
      return renderStandard(g as Gsel, seqLen, dModel, nHeads, W);
  }
}